type MatchRuleProfile={ageGroup:string;allowedEvents:string[];offside:boolean;cards:boolean;substitutions:boolean;injuries:boolean;corners:boolean};
const defaultMatchRuleEvents=['Goal','Yellow card','Red card','Substitution','Injury','Offside','Corner'];
function matchRuleProfile(ageGroup:string):MatchRuleProfile{const normalized=ageGroup.toUpperCase();const uNumber=Number(normalized.replace(/[^0-9]/g,''))||0;const offside=uNumber>=12;return {ageGroup,allowedEvents:offside?defaultMatchRuleEvents:['Goal','Substitution','Injury','Corner'],offside,cards:uNumber>=12,substitutions:true,injuries:true,corners:true};}
