const validRoles:UserRole[]=['Supporter','Manager','Club','LFA Admin'];
function requireLfaAdmin(): RouterMiddleware {
  return async (ctx) => {
    const userId=ctx.user?.userId;
    if(!userId)return error('Unauthorized',401);
    const roles=await listTable<{userId:string;role:UserRole}>('user_roles');
    const role=roles.find(r=>r.userId===userId)?.role;
    if(role!=='LFA Admin')return error('LFA Admin role required',403);
  };
}
function requireAnyRole(allowed:UserRole[]): RouterMiddleware { return async (ctx) => { const userId=ctx.user?.userId; if(!userId)return error('Unauthorized',401); const roles=await listTable<{userId:string;role:UserRole}>('user_roles'); const role=roles.find(r=>r.userId===userId)?.role||'Supporter'; if(!allowed.includes(role))return error('Insufficient role permissions',403); }; }
type RoleAssignment={userId:string;role:UserRole;club?:string;team?:string;leagueId?:string;clubId?:string;teamId?:string;managerId?:string};
function normalizeScope(value:string){return value.toLowerCase().replace(/\s+fc$/,'').replace(/\s+u[0-9]+$/,'').trim();}
function clubNameFromTeam(teamName:string){return teamName.replace(/\s+u[0-9]+$/i,'').trim();}
async function ensureLeagueIdentity(){
  const leagues=await listTable<LeagueRecord>('leagues');
  let league=leagues[0];
  if(!league){const [id]=await db.add('leagues',[{name:'2026 Community League',season:'2026',country:'South Africa',status:'Active',createdAt:Date.now()}]);league={id:id||undefined,name:'2026 Community League',season:'2026',country:'South Africa',status:'Active',createdAt:Date.now()};}
  const teams=await listTable<Team>('teams');
  let clubs=await listTable<ClubRecord>('clubs');
  const clubMap=new Map<string,ClubRecord>();
  clubs.forEach(c=>clubMap.set(normalizeScope(c.name),c));
  for(const team of teams){
    const clubName=clubNameFromTeam(team.name);
    const key=normalizeScope(clubName);
    if(!clubMap.has(key)){const [id]=await db.add('clubs',[{leagueId:league.id,name:clubName,shortName:clubName.replace(/\s+/g,' ').slice(0,24),status:'Active',createdAt:Date.now()}]);if(id)clubMap.set(key,{id,leagueId:league.id!,name:clubName,shortName:clubName,status:'Active',createdAt:Date.now()});}
    const club=clubMap.get(key);
    if(club?.id&&team.id){const record={...team,leagueId:league.id,clubId:club.id,teamId:team.id};await db.update('teams',[{id:team.id,record}]);}
  }
  const refreshedTeams=await listTable<IdentityTeam>('teams');
  const refreshedClubs=await listTable<ClubRecord>('clubs');
  const players=await listTable<Player>('players');
  const teamByName=new Map(refreshedTeams.map(t=>[t.name,t]));
  for(const player of players){const team=teamByName.get(player.team);if(team?.id&&player.id){const record={...player,leagueId:league.id,clubId:team.clubId,teamId:team.id,playerId:player.memberRef};await db.update('players',[{id:player.id,record}]);}}
  return {league,clubs:refreshedClubs,teams:await listTable<IdentityTeam>('teams'),players:await listTable<IdentityPlayer>('players')};
}
async function getRoleAssignment(userId:string):Promise<RoleAssignment>{const rows=await listTable<RoleAssignment>('user_roles');const found=rows.find(r=>r.userId===userId);const own:RoleAssignment=found||{userId,role:'Supporter'};if(own.role==='LFA Admin')return own;const identity=await ensureLeagueIdentity();const legacyClub=own.club?identity.clubs.find(c=>normalizeScope(c.name)===normalizeScope(own.club!)):undefined;const legacyTeam=own.team?identity.teams.find(t=>t.name===own.team):undefined;return {...own,leagueId:own.leagueId||identity.league.id,clubId:own.clubId||legacyClub?.id,teamId:own.teamId||legacyTeam?.id};}
function teamBelongsToClub(team:string,club:string){return normalizeScope(team)===normalizeScope(club);}
function scopedTeamAccess(resolve:(ctx:Parameters<RouterMiddleware>[0])=>Promise<string|undefined>):RouterMiddleware{return async(ctx)=>{const userId=ctx.user?.userId;if(!userId)return error('Unauthorized',401);const assignment=await getRoleAssignment(userId);if(assignment.role==='LFA Admin')return;const target=String(await resolve(ctx)||'').trim();if(!target)return error('Team scope is required',400);const identity=await ensureLeagueIdentity();const team=identity.teams.find(t=>t.id===target||t.name===target||t.teamId===target);if(!team)return error('Team not found',404);if(assignment.role==='Manager'&&((assignment.teamId&&assignment.teamId===team.id)||assignment.team===team.name))return;if(assignment.role==='Club'&&assignment.clubId&&assignment.clubId===team.clubId)return;if(assignment.role==='Club'&&assignment.club&&teamBelongsToClub(team.name,assignment.club))return;return error('You do not have access to this team',403);};}
function scopedClubAccess(resolve:(ctx:Parameters<RouterMiddleware>[0])=>Promise<string|undefined>):RouterMiddleware{return async(ctx)=>{const userId=ctx.user?.userId;if(!userId)return error('Unauthorized',401);const assignment=await getRoleAssignment(userId);if(assignment.role==='LFA Admin')return;const target=String(await resolve(ctx)||'').trim();if(!target)return error('Club scope is required',400);const identity=await ensureLeagueIdentity();const club=identity.clubs.find(c=>c.id===target||normalizeScope(c.name)===normalizeScope(target));if(!club)return error('Club not found',404);if((assignment.role==='Club'||assignment.role==='Manager')&&assignment.clubId===club.id)return;if((assignment.role==='Club'||assignment.role==='Manager')&&assignment.club&&normalizeScope(club.name)===normalizeScope(assignment.club))return;return error('You do not have access to this club',403);};}
function scopedFixtureAccess(resolve:(ctx:Parameters<RouterMiddleware>[0])=>Promise<string|undefined>):RouterMiddleware{return async(ctx)=>{const userId=ctx.user?.userId;if(!userId)return error('Unauthorized',401);const assignment=await getRoleAssignment(userId);if(assignment.role==='LFA Admin')return;const fixtureId=String(await resolve(ctx)||'').trim();if(!fixtureId)return error('Fixture scope is required',400);const fixture=(await db.get<Fixture>('fixtures',[fixtureId]))[0];if(!fixture)return error('Fixture not found',404);const identity=await ensureLeagueIdentity();const home=identity.teams.find(t=>t.id===fixture.homeTeamId||t.name===fixture.home);const away=identity.teams.find(t=>t.id===fixture.awayTeamId||t.name===fixture.away);if(assignment.role==='Manager'&&assignment.clubId&&(home?.clubId===assignment.clubId||away?.clubId===assignment.clubId))return;if(assignment.role==='Manager'&&assignment.club&&((home&&normalizeScope(home.name).startsWith(normalizeScope(assignment.club)))||(away&&normalizeScope(away.name).startsWith(normalizeScope(assignment.club)))))return;if(assignment.role==='Manager'&&assignment.teamId&&(home?.id===assignment.teamId||away?.id===assignment.teamId))return;if(assignment.role==='Manager'&&assignment.team&&(fixture.home===assignment.team||fixture.away===assignment.team))return;if(assignment.role==='Club'&&assignment.clubId&&(home?.clubId===assignment.clubId||away?.clubId===assignment.clubId))return;if(assignment.role==='Club'&&assignment.club&&(teamBelongsToClub(fixture.home,assignment.club)||teamBelongsToClub(fixture.away,assignment.club)))return;return error('You do not have access to this fixture',403);};}
function invoiceStatus(dueDate:string,status:'Due'|'Paid'|'Overdue'='Due'):'Due'|'Paid'|'Overdue'{if(status==='Paid')return 'Paid';return dueDate<'2026-09-13'?'Overdue':'Due';}

